import type { RequestHandler } from "@builder.io/qwik-city";
import db from "../../../../../lib/db";
import { generateApiKey, hashApiKey } from "../../../../../lib/crypto";

export const onPost: RequestHandler = async ({ request, json }) => {
  let body: any;
  try {
    body = await request.json();
  } catch (e) {
    return json(400, { error: "Invalid JSON body" });
  }

  if (!body || typeof body.name !== "string" || body.name.trim() === "") {
    return json(400, { error: "Name is required and must be a non-empty string" });
  }

  const name = body.name.trim();
  const rawKey = generateApiKey();
  const prefix = rawKey.substring(0, 7);
  const hashedKey = hashApiKey(rawKey);
  const createdAt = new Date().toISOString();

  try {
    const stmt = db.prepare(`
      INSERT INTO api_keys (name, key_prefix, hashed_key, status, created_at)
      VALUES (?, ?, ?, ?, ?)
    `);
    const result = stmt.run(name, prefix, hashedKey, "active", createdAt);
    const id = Number(result.lastInsertRowid);

    return json(201, {
      id,
      name,
      prefix,
      key: rawKey,
      status: "active",
      created_at: createdAt,
    });
  } catch (error: any) {
    return json(500, { error: "Database error: " + error.message });
  }
};

export const onGet: RequestHandler = async ({ json }) => {
  try {
    const stmt = db.prepare(`
      SELECT id, name, key_prefix, status, created_at
      FROM api_keys
      ORDER BY id DESC
    `);
    const rows = stmt.all();

    const result = rows.map((row: any) => ({
      id: row.id,
      name: row.name,
      prefix: row.key_prefix,
      status: row.status,
      created_at: row.created_at,
    }));

    return json(200, result);
  } catch (error: any) {
    return json(500, { error: "Database error: " + error.message });
  }
};

import type { RequestHandler } from "@builder.io/qwik-city";
import db from "../../../../../../lib/db";

export const onPost: RequestHandler = async ({ params, json }) => {
  const id = Number(params.id);
  if (isNaN(id)) {
    return json(400, { error: "Invalid ID parameter" });
  }

  try {
    const checkStmt = db.prepare("SELECT id FROM api_keys WHERE id = ?");
    const row = checkStmt.get(id);

    if (!row) {
      return json(404, { error: "Key not found" });
    }

    const updateStmt = db.prepare("UPDATE api_keys SET status = 'revoked' WHERE id = ?");
    updateStmt.run(id);

    return json(200, {
      success: true,
      message: `API key with ID ${id} has been successfully revoked.`,
    });
  } catch (error: any) {
    return json(500, { error: "Database error: " + error.message });
  }
};

import type { RequestHandler } from "@builder.io/qwik-city";
import db from "../../../../lib/db";
import { hashApiKey } from "../../../../lib/crypto";

export const onGet: RequestHandler = async ({ request, headers, json }) => {
  const apiKey = headers.get("X-API-Key") || request.headers.get("X-API-Key");

  if (!apiKey) {
    return json(401, { error: "Unauthorized" });
  }

  if (!apiKey.startsWith("qk_") || apiKey.length !== 35) {
    return json(401, { error: "Unauthorized" });
  }

  const prefix = apiKey.substring(0, 7);
  const hashedKey = hashApiKey(apiKey);

  try {
    const stmt = db.prepare(`
      SELECT id FROM api_keys
      WHERE key_prefix = ? AND hashed_key = ? AND status = 'active'
    `);
    const row = stmt.get(prefix, hashedKey);

    if (!row) {
      return json(401, { error: "Unauthorized" });
    }

    return json(200, {
      message: "Hello, authenticated developer!",
    });
  } catch (error: any) {
    return json(500, { error: "Database error: " + error.message });
  }
};

